"""A book of trades with a cached total."""


class TradeBook:
    def __init__(self):
        self._trades = []
        self._total = None

    def add(self, trade):
        """Add one trade to the book."""
        self._trades.append(trade)

    def total(self):
        """Return the total volume of the trades in the book."""
        if self._total is None:
            self._total = sum(x.volume for x in self._trades)
        return self._total

    def count(self):
        """Return how many trades the book holds."""
        return len(self._trades)


def describe_trade(trade):
    """Return a one-line description of a trade."""
    return "%s: %s" % (trade.desk, trade.volume)

